#!/usr/bin/env python3
"""Assemble docs/re/*.md from the analysis outputs in out/. Re-run after re-running the tools.
Usage: make_docs.py <workdir>   (expects out/*.json and docs/ to exist)"""
import sys, os, json, collections, datetime
W = sys.argv[1] if len(sys.argv) > 1 else '.'
O = lambda p: json.load(open(os.path.join(W, 'out', p)))
D = lambda p: os.path.join(W, 'docs', p)

def pe_overview():
    a, b, p, t = O('pe_foc.json'), O('pe_eaw.json'), O('pe_perc.json'), O('pe_tbb.json')
    L = ['# StarWarsG.exe (FoC, Steam x64) - PE overview', '',
         'Generated by `tools/re/pe_overview.py` + `tools/re/make_docs.py`. All addresses are RVAs (image base 0x140000000).', '',
         '| property | FoC `corruption\\StarWarsG.exe` | EaW `GameData\\StarWarsG.exe` |', '|---|---|---|']
    for k in ('size', 'sha256', 'timestamp', 'linker', 'entry_rva', 'rtti_type_descriptors'):
        va, vb = a[k], b[k]
        if k == 'timestamp':
            va = datetime.datetime.fromtimestamp(va, datetime.timezone.utc).isoformat(); vb = datetime.datetime.fromtimestamp(vb, datetime.timezone.utc).isoformat()
        L.append(f'| {k} | {va} | {vb} |')
    L.append(f"| PDB | {a['debug'][0].get('pdb')} (path only, no symbols shipped) | {b['debug'][0].get('pdb')} |")
    L.append(f"| version | {a['version_info'].get('FileDescription')} / Product {a['version_info'].get('ProductVersion')} | {b['version_info'].get('ProductName')} |")
    L += ['', '**Compiler**: MSVC 2019 (linker 14.29; Rich header prodids 259/260/261 = VS2019 C/C++/link, builds 27412-30151), '
          'statically linked UCRT/STL (no MSVCP/VCRUNTIME imports), full MSVC **RTTI present** (1703 type descriptors, 1992 complete-object '
          'locators). x64 `.pdata` gives exact function bounds: **37,543 functions**. Both executables were rebuilt 2024-10-04 from the same '
          'code base (same import set); EaW lacks the FoC-only classes (corruption, Underworld abilities, etc.).', '',
          '## Sections (FoC)', '', '| name | RVA | vsize | raw | flags | entropy |', '|---|---|---|---|---|---|']
    for s in a['sections']:
        L.append(f"| {s['name']} | {s['va']} | {s['vsize']} | {s['rawsize']} | {s['flags']} | {s['entropy']} |")
    L += ['', '`.data` vsize >> raw size (0x175ec0 vs 0x91e00): ~0xE4000 bytes of BSS (globals/singletons, pools).', '',
          '## Imports by DLL (FoC)', '', '| DLL | # | what it tells us |', '|---|---|---|']
    notes = {'d3d9.dll': 'Only `Direct3DCreate9` (no D3D9Ex). Renderer is plain D3D9; the installed d3d9.dll is DXVK 3.1.1 (D3D9->Vulkan).',
             'd3dx9_43.dll': 'D3DX Effects framework (`D3DXCreateEffect`, `D3DXCreateEffectPool`, `D3DXCreateEffectCompilerFromFileA`), texture load/save, math. Shaders are `.fx` effects (fx_2_0) driven through ID3DXEffect.',
             'mss64.dll': 'Miles Sound System (AIL_*): 2D samples, 3D positional samples, streams.',
             'bink2w64.dll': 'Bink 2 video (BinkOpen/DoFrame/CopyToBuffer, BinkOpenMiles for audio).',
             'steam_api64.dll': 'Steamworks flat API (init, callbacks, call results); lobby/P2P networking + Workshop (`STEAMMOD=`).',
             'PerceptionFunctionG.dll': 'AI perception-equation DLL (see below).',
             'WS2_32.dll': 'UDP sockets (sendto/recvfrom) for LAN/legacy MP; WinsockAsyncSocketImpl.',
             'KERNEL32.dll': 'Threads (CreateThread x1 call site), events, critical sections, file mapping (profile), QPC timing.',
             'WINMM.dll': 'timeBeginPeriod/timeGetTime (frame timing).', 'USER32.dll': 'Window, message pump, raw keyboard/mouse via messages + GetAsyncKeyState (no DirectInput/XInput imports).',
             'POWRPROF.dll': 'CallNtPowerInformation (CPU speed query).'}
    for d, f in a['imports'].items():
        L.append(f"| {d} | {len(f)} | {notes.get(d, ', '.join(f[:6]) + (' ...' if len(f) > 6 else ''))} |")
    L += ['', 'Not imported: DirectInput, XInput, DirectSound, XAudio, OpenGL, **Intel TBB**, any Lua DLL.', '',
          '## Lua', '', '- **Lua 5.0.2, statically linked** (`$Lua: Lua 5.0.2 Copyright (C) 1994-2004 Tecgraf, PUC-Rio $`). Both the parser '
          "(`` `=' or `in' expected``, `unfinished string`)" ' and the undumper (`bad code in %s`, `virtual machine mismatch in %s: size of %s is %d but read %d`, '
          '`size_t`, `Instruction`) are present, so `lua_load` accepts **both source and precompiled chunks**, auto-detected by the `\\033Lua` signature.',
          '- The undump header check compares `sizeof(size_t)`/`sizeof(Instruction)`/`sizeof(lua_Number)`; retail 32-bit bytecode (config.meg) '
          'has 4-byte `size_t` and is rejected by this x64 VM. That is why 64Patch.meg ships plain-text sources for every script.',
          '- `LUA_PATH` default `./?.lua;./?.lc`; `?;?.lua` in `require`. Engine-side bindings: see `LUA_API.md`.', '',
          '## Other statically linked libraries', '', '- zlib 1.2.11 (deflate/inflate) - savegames/MP transfer compression.',
          '- MSVC STL/UCRT; boost (in PerceptionFunctionG.dll only: boost::spirit classic for the equation grammar).', '',
          '## Companion binaries', '',
          f"- **PerceptionFunctionG.dll** ({p['size']} bytes, PDB `{p['debug'][0].get('pdb')}`): imports only KERNEL32/USER32/WINMM; exports "
          f"{len(p.get('exports', []))} C++ symbols (`ThePerceptionFunctionManagerClass::System_Initialize(MegaFileManagerClass*, bool)`, "
          '`Read_Equation_File`, `PerceptionFunctionClass::Build/Evaluate(PerceptionContextClass const&, double&)`, `Init_Perception_DLL(...)`). '
          'The exe passes callbacks into `Init_Perception_DLL` (token-to-value evaluator, allocator, string conversions) and the DLL '
          'parses `Data/XML/AI/PerceptualEquations/*.xml` into expression trees (AdditionOperatorNodeClass, ClampFunctionNodeClass, ... '
          '125 RTTI classes in `rtti_perception_dll.txt`). Evaluation is a pure function of a PerceptionContext -> safe to run on worker threads '
          'if the token callbacks are made read-only.',
          f"- **tbbR.dll** (Intel TBB 2.x-era API: task_scheduler_init, concurrent_queue/vector, pipeline; 216 exports; built {datetime.datetime.fromtimestamp(t['timestamp'], datetime.timezone.utc).date()}): "
          '**not imported or LoadLibrary\'d by StarWarsG.exe, the EaW exe, or PerceptionFunctionG.dll**, and no `tbb` strings exist in the exe. '
          'The engine does not use it; it is a redistributable leftover (probably for the launcher/crash tooling). The engine is effectively '
          'single-threaded: the only `CreateThread` call site (`0x786138`, via ThreadClass at `0x22e490`) is used by the loading-screen thread, '
          'network packet/NAT threads (PacketHandlerClass, NATUtilsThreadClass) and BattleLoadDialog.',
          '- `d3d9.dll`/`dxgi.dll` in `corruption\\` = DXVK v3.1.1 (log: Vulkan device AMD RX 9070 XT).',
          '- `d3dx9_43.dll` in `corruption\\` is **not Microsoft\'s**: it is the entry of the third-party patch proxy chain (see `PRIOR_PATCH.md`); '
          'the genuine D3DX is renamed `eaw_modifier_d3dx_original.dll`.']
    open(D('PE_OVERVIEW.md'), 'w').write('\n'.join(L) + '\n')

