CHAIN = ['d3dx9_43.dll', 'eaw_mesh_material_v2_backend.dll', 'eaw_geometry_preparation_backend.dll', 'eaw_render_task_backend.dll', 'eaw_memory_backend.dll',
         'eaw_simulation_backend.dll', 'eaw_ai_work_backend.dll', 'eaw_ai_pacing_backend.dll', 'eaw_effect_setters_backend.dll', 'eaw_visibility_unified.dll',
         'eaw_unified_modifier_v1.dll', 'eaw_geometry_d3dx_original.dll', 'eaw_direct_r13.dll', 'eaw_modifier_d3dx_original.dll']

def prior_patch():
    sig = O('patch_sigs_filtered.json'); ctx = O('patched_fn_context.json'); inv = O('patch_inventory.json')
    import pickle
    sys.path.insert(0, os.path.dirname(__file__))
    from locality import nearest
    lab, keys = pickle.load(open(os.path.join(W, 'out', 'locality.pkl'), 'rb'))
    L = ['# Prior in-process optimization patch ("unified-complete-component-regression-v2")', '',
         'Static inventory only (DLLs treated as data, never loaded). Tools: `tools/re/patch_inventory.py` (exports/imports/strings), '
         '`tools/re/patch_sigs.py` (finds exe RVAs for which the DLL embeds the exe\'s original bytes - i.e. hook-site signatures; filtered to '
         '>=12-byte signatures that are unique in the exe), `tools/re/name_fn.py` + `locality.py` (attribution).', '',
         '## Mechanism', '',
         '- **Loader**: the game imports `d3dx9_43.dll`; the file in `corruption\\` is a 88 KB proxy. Each DLL re-exports the ~330 D3DX entry '
         'points by forwarding to the next DLL, forming a 14-link chain ending at `eaw_modifier_d3dx_original.dll` = the genuine Microsoft '
         'd3dx9_43 (2.4 MB). File names are rotated relative to content (each file exports the *previous* feature\'s anchor):', '',
         '  ' + ' -> '.join(f'`{c}`' for c in CHAIN), '',
         '- Built with llvm-mingw; patches code with `VirtualProtect`-style writes + `FlushInstructionCache` and registers trampolines with '
         '`RtlAddFunctionTable`; embeds 64-byte copies of the original code at every site and verifies them before patching (that is what '
         '`patch_sigs.py` keys on). The install manifest pins `engine_sha256` = this exe\'s SHA-256 (07daeeae...), so hooks are RVA-exact for v1.121.', '',
         '- Telemetry: `eaw_effect_probe_v4.csv` (one session): SetValue 113.2M, SetVector 61.5M, SetTexture 32.7M, Begin/End 29.8M, '
         'BeginPass/EndPass 29.9M, SetFloat 23.4M, SetMatrixArray 6.65M, CommitChanges 6.33M, SetTechnique 89, 85 effects. ~1.2M of 1.77M sampled '
         'raw sets were redundant (same value) -> redundant effect-parameter traffic is a real render-CPU cost.', '',
         '## Hot spots by feature (DLL -> verified hook sites)', '']
    summary = []
    for dll in CHAIN[:-1]:
        feat, ini = PATCH_FEATURE.get(dll, ('?', '?'))
        hits = sig.get(dll, [])
        fns = collections.OrderedDict()
        for h in hits:
            f = h['function'] or h['rva']
            fns.setdefault(f, []).append(h['rva'])
        L += [f'### `{dll}` - {feat}', '', f'Config: `{ini}`. Own exports: ' +
              ', '.join(f'`{e}`' for e in inv.get(dll, {}).get('exports', []) if not e.startswith('D3DX')) + '.', '']
        if not fns:
            L += ['No unique code-signature sites: works by wrapping D3DX objects (effects) returned through the forwarded API.', '']
            continue
        L += ['| exe function | patched offsets | attribution |', '|---|---|---|']
        for f, rvas in fns.items():
            fi = int(f, 16)
            c = ctx.get(f, {})
            attr = []
            if c.get('vtable_slots'): attr.append('vtable ' + ', '.join(c['vtable_slots'][:3]))
            nn = nearest(lab, keys, fi, 1)
            if nn: attr.append(f"TU ~{nn[0][1]} (+-{nn[0][2]})")
            if c.get('strings'): attr.append('strings: ' + '; '.join(s[:50] for s in c['strings'][:2]))
            offs = ', '.join(hex(int(r, 16) - fi) for r in rvas[:8])
            L.append(f"| `{f}` | {offs} | {' / '.join(attr)} |")
            summary.append((dll, f, attr))
        L.append('')
    L += ['## What this says about the real hot spots', '',
          '1. **AI goal servicing** - AIGoalSystemClass vtable slots [2]/[4] (0x6cacd0, 0x6ca9a0) and their helpers (0x6c76f0..0x6cb120, '
          'PotentialPlanClass 0x6c0be0, block-status TU 0x7218xx-0x7229xx) are time-sliced by `ai_pacing` (6 ms budget). This matches the known '
          'campaign-map stutter: AI service runs synchronously on the game thread every galactic tick.',
          '2. **Perception evaluation** - FindTargetClass (Lua `FindTarget`, 0x698360-0x698dac), PerceptionParameterBindings (0x3ef160) and a '
          'name/CRC lookup used by both LuaScriptClass and AI perception nodes (0x241df0) get scratch buffers and "best-only" scoring '
          '(`ai_work`) - i.e. the original builds and sorts full candidate lists per query.',
          '3. **Spatial queries / culling** - TreeCullClass/CullSystemClass (0x20bb60-0x210406) and GameObjectManager radius queries '
          '(0x2abcf0, 0x2acb90, used by ProjectileBehavior) are patched by `visibility` and `simulation_query`. One tree serves render culling '
          'and gameplay; replacing it (BVH/grid, parallel queries) is the highest-leverage engine change.',
          '4. **Targeting / damage modifiers** - TeamTargetingBehaviorClass vtable[40] (0x566ca0), HardPointClass functions (0x3857d0, 0x385ae0), '
          'the Take_Damage path (0x38e0c0) and GameObjectTypeClass lookup (0x3727a0) are "direct modifier" call sites; `modifier merge` bulk-merges '
          'stat modifiers (0x27da40 FrameSynchronizer/Player TU, 0x536330/0x536570).',
          '5. **Allocation churn** - operator new (0x769c58) and DynamicVector growth (0x45480/0x45580/0x48410) are hooked for pooling '
          '(`memory`: ai_context, path_temporaries incl. SpacePathFinderClass TU 0x597dc0-0x598100).',
          '6. **Renderer CPU** - alMeshRenderTask [0]/[2] (0x15e290/0x15e1a0), alRenderableMesh[8] (0x14c270), particle emission/geometry '
          '(alParticles TU 0x162c60-0x173400), alHModel (0x12c7c0, 0x12d2c0) and D3DX effect parameter setters - render-task pooling, '
          'batched CPU vertex prep and a render worker thread.', '',
          '## Caveats', '',
          '- Only signature-verified sites are listed; patches that locate code by other means (pattern scans at runtime, vtable swaps, IAT hooks on '
          'D3DX objects) are under-reported. A second pass with a disassembler on the DLLs\' install routines (look for the `patches` table - '
          'symbol `_ZL7patches` with `Signature`/`Target` fields) would give the authoritative list.',
          '- Attribution of unnamed functions is by address locality; treat as "in or next to the TU of X".']
    open(D('PRIOR_PATCH.md'), 'w').write('\n'.join(L) + '\n')

